## ---- setup ----
source("_common.R")
library(tidypm)
library(knitr)

## ---- data ----
R  <- as_xts_pm(sim_class_returns_monthly, date, class, return)
rf <- sim_riskfree_monthly$return
Re <- R - rf
stopifnot(ncol(Re) == 16L, !anyNA(Re), length(rf) == nrow(R))

# ===== What an information ratio is estimating =====

## ---- months-needed ----
# Months of data before an information ratio has a t-statistic of two,
# by eq-24-se applied per month and the ratio quoted per year.
months_needed <- function(ir_annual, t_stat = 2) {
  ir_m <- ir_annual / sqrt(12)
  (1 + ir_m^2 / 2) / (ir_m / t_stat)^2
}
round(c(months = months_needed(0.5), years = months_needed(0.5) / 12), 1)

# ===== A policy portfolio and a manager =====

## ---- policy ----
sleeve_of <- function(a) dplyr::case_when(
  grepl("_equity$", a)     ~ "equity",
  grepl("_government$", a) ~ "government",
  grepl("_credit$", a)     ~ "credit",
  TRUE                     ~ "commodity")

sleeve_policy <- c(equity = 0.50, government = 0.30, credit = 0.15, commodity = 0.05)
sl <- sleeve_of(colnames(R))

# each sleeve's weight spread equally over its members, and indexed by name so
# that b can never be paired with the wrong column of R
b <- setNames(sleeve_policy[sl] / as.numeric(table(sl)[sl]), colnames(R))
stopifnot(abs(sum(b) - 1) < 1e-12, identical(names(b), colnames(R)))

## ---- tbl-24-policy ----
# The policy benchmark. Sleeve weights are stated, not estimated; within a
# sleeve the members are equally weighted.
tibble::tibble(sleeve = names(sleeve_policy),
               members = as.integer(table(sl)[names(sleeve_policy)]),
               sleeve_weight = sleeve_policy,
               per_class = sleeve_policy / as.integer(table(sl)[names(sleeve_policy)])) |>
  dplyr::mutate(dplyr::across(c(sleeve_weight, per_class), ~ sprintf("%.1f%%", 100 * .x))) |>
  kable(align = "lrrr", col.names = c("", "classes", "sleeve weight", "weight per class"))

## ---- register-rank ----
# the manager's place in the register of chapter 25 is read, not typed
reg <- read.csv("tables/oos-sweep.csv") |>
  dplyr::filter(universe == "classes", window == 60L, frequency == "months", basis == "gross")
stopifnot(nrow(reg) == 5L, "min_variance" %in% reg$strategy)
rank_mv <- rank(-reg$sharpe)[reg$strategy == "min_variance"]
stopifnot(rank_mv == 2L)

## ---- active-portfolio ----
win <- 60L
spec_mv <- portfolio.spec(assets = colnames(Re)) |>
  add.constraint(type = "full_investment") |>
  add.constraint(type = "long_only") |>
  add.objective(type = "risk", name = "var")

bt <- optimize.portfolio.rebalancing(
  Re, spec_mv, optimize_method = "ROI",
  rebalance_on = "months", training_period = win, rolling_window = win - 1L)

W_act <- extractWeights(bt)
stopifnot(all(diagnose_rebalancing(bt)$status == "converged"),
          identical(colnames(W_act), colnames(R)))
c(rebalances = nrow(W_act), first = fmt_model(zoo::index(W_act)[1]))

# ===== Two return series, and the trap between them =====

## ---- backfill ----
msg <- tryCatch(Return.portfolio(R, weights = W_act),
                warning = function(w) conditionMessage(w))
msg

# ===== The benchmark comparison starts with a portfolio nobody chose =====

## ---- returns ----
first_w <- zoo::index(W_act)[1]
R_oos   <- R[zoo::index(R) > first_w]             # the months a weight vector precedes
rf_oos  <- xts::xts(rf[zoo::index(R) > first_w], order.by = zoo::index(R_oos))

Rp <- Return.portfolio(R_oos, weights = W_act)                       # rebalanced monthly
Rb <- Return.portfolio(R_oos, weights = b, rebalance_on = "months")  # to constant b
colnames(Rp) <- "active"; colnames(Rb) <- "policy"

# the last weight vector has no month after it; every other one is used once
W_used <- zoo::coredata(W_act)[-nrow(W_act), ]
stopifnot(nrow(W_used) == nrow(R_oos),
          all.equal(as.numeric(Rp), rowSums(W_used * zoo::coredata(R_oos))),
          all.equal(as.numeric(Rb), as.numeric(zoo::coredata(R_oos) %*% b)))

a <- Rp - Rb                                    # the active return of eq-24-te
colnames(a) <- "active_return"
c(months = nrow(a), from = fmt_model(zoo::index(a)[1]))

# ===== The measures in PerformanceAnalytics =====

## ---- measures ----
te_pa <- TrackingError(Rp, Rb)
ap_pa <- ActivePremium(Rp, Rb)
ir_pa <- InformationRatio(Rp, Rb)
ir_ar <- InformationRatio(Rp, Rb, geometric = FALSE)
ir_hand <- mean(a) / stats::sd(a) * sqrt(12)
stopifnot(all.equal(as.numeric(ir_ar), ir_hand),
          ir_ar < 0)                      # the prose below reads the sign

round(c(tracking_error = te_pa, active_premium = ap_pa,
        IR_default = ir_pa, IR_arithmetic = ir_ar), 4)

# ===== The default information ratio is not @eq-24-ir =====

## ---- capture ----
capture <- table.CaptureRatios(Rp, Rb)
up_months <- UpDownRatios(Rp, Rb, method = "Number", side = "Up")
dn_months <- UpDownRatios(Rp, Rb, method = "Number", side = "Down")
round(c(up_capture = capture[["Up Capture"]], down_capture = capture[["Down Capture"]],
        share_up_when_bench_up = up_months, share_down_when_bench_down = dn_months), 3)

## ---- capm ----
beta_b  <- CAPM.beta(Rp, Rb, Rf = rf_oos)
alpha_b <- CAPM.alpha(Rp, Rb, Rf = rf_oos)           # per month
appr    <- AppraisalRatio(Rp, Rb, Rf = rf_oos)       # Jensen alpha over residual risk
stopifnot(alpha_b > 0, appr > 0, ir_ar < 0)          # the two signs the prose reconciles
round(c(beta = beta_b, alpha_annual = 12 * alpha_b, appraisal_ratio = appr), 4)

## ---- tbl-24-capm ----
